const base = "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const files = [
  `${base}/AlgebraicJacobian/Picard/JacobianDataCharts.lean`,
  `${base}/AlgebraicJacobian/Picard/Pic0AtlasFromDivRep.lean`,
  `${base}/AlgebraicJacobian/Picard/Pic0ChartLocusClass.lean`,
  `${base}/AlgebraicJacobian/Picard/DivRepKit.lean`
];
const results = await Promise.all(files.map(file_path =>
  tools.mcp__lean_lsp__lean_file_outline({file_path})
));
for (let i = 0; i < results.length; i++) {
  text(`---${files[i]}---`);
  for (const item of results[i].content ?? []) {
    if (item.type === "text") text(item.text);
    else if (item.type === "image") image(item);
  }
}
